from opentelemetry import trace, propagate
from opentelemetry.trace import SpanKind

tracer = trace.get_tracer("checkout")

# --- PRODUCER (Checkout Service): inject context INTO the message ---
def publish_order(queue, order):
    with tracer.start_as_current_span("publish_order", kind=SpanKind.PRODUCER):
        carrier = {}
        propagate.inject(carrier)              # writes 'traceparent' into carrier
        queue.send(
            body=order,
            attributes={"traceparent": carrier["traceparent"]},
        )

# --- CONSUMER (Fulfilment Worker): extract context FROM the message ---
def handle_message(msg):
    carrier = {"traceparent": msg.attributes.get("traceparent", "")}
    ctx = propagate.extract(carrier)           # rebuilds parent context
    with tracer.start_as_current_span(
        "fulfil_order", context=ctx, kind=SpanKind.CONSUMER
    ):
        fulfil(msg.body)                       # now a CHILD of publish_order

