# SLO protected: p99 checkout < 800ms AND 99.9% availability
breaker = CircuitBreaker(
    fail_max=5,            # trip OPEN after 5 failures in the window
    reset_timeout=30,      # after 30s, allow ONE HALF-OPEN probe
)

@breaker
def call_payments(order):
    # bound EVERY attempt — an unbounded call is the root cause
    for attempt in range(2):                     # 1 retry, not 5
        try:
            return payments.charge(order, timeout=0.25)   # 250ms cap
        except Timeout:
            sleep(backoff(attempt) + jitter())   # jitter breaks the herd
    raise Timeout()

def checkout(order):
    breaker_state.labels(dep="payments").set(breaker.state_code)  # emit metric
    try:
        return call_payments(order)
    except (Timeout, CircuitBreakerError):
        payments_fallback.inc()                  # count the shed load
        return queue_for_async_capture(order)    # fallback: 'pay later', journey lives
